mutations.before:
for (const b of densityGroupEl.querySelectorAll(".ib-density-seg")) {
  const on = (b as HTMLElement).dataset.density === state.density;
  b.classList.toggle("is-active", on);
  b.setAttribute("aria-pressed", String(on));
}

mutations.after:
for (const btn of densityGroupEl.querySelectorAll(".ib-density-seg")) {
  const on = (btn as HTMLElement).dataset.density === state.density;
  btn.classList.toggle("is-active", on);
  btn.setAttribute("aria-pressed", String(on));
}
